scan_linter_check.script:
(function(engine) {
    if (!engine.rootNode) {
        return;
    }
    var max = global.EcsConfig.getInt('complexity.max', 10);
    var hits = new global.EcsComplexity(new global.EcsAst(engine.rootNode)).overLimit(max);
    var report = new global.EcsReport(engine, {
        ruleId: 'SN-COMPLEXITY-001',
        title: 'Excessive function complexity',
        recommendation: 'Split the function into smaller functions with one responsibility each, replace long ' +
            'if/else or switch chains with lookup tables, and return early instead of nesting. Complex functions ' +
            'are harder to test and review. The limit is set by the system property ecs.complexity.max.'
    });
    for (var i = 0; i < hits.length; i++) {
        report.add(hits[i].node, hits[i].message);
    }
    report.flush();
})(engine);
